// Throwaway study: three structural directions + selected synthesis. All data/results are fixtures.
import { EditorView, basicSetup } from 'codemirror';
import { EditorState, Compartment } from '@codemirror/state';
import { html } from '@codemirror/lang-html';
import { oneDark } from '@codemirror/theme-one-dark';
const variants=['developer','guided','academy','synthesis'];
const names={developer:'A · Developer Workspace',guided:'B · Guided Learning',academy:'C · Technical Academy',synthesis:'Selected · Learning Workshop'};
const screens=['dashboard','path','lesson','check','challenge','boss','progress'];
const labels={dashboard:'Dashboard',path:'Learning Path',lesson:'Lesson',check:'Knowledge Check',challenge:'Challenge',boss:'Boss Challenge',progress:'Progress & evidence'};
const params=new URLSearchParams(location.search);
let variant=variants.includes(params.get('variant'))?params.get('variant'):'synthesis';
let screen=screens.includes(params.get('screen'))?params.get('screen'):'dashboard';
let state=params.get('state')||'ready';
let view, pane=['failed','completed','network','submitted'].includes(state)?'output':'code', output='feedback', quizDone=false;
const docs={challenge:'<!-- Build a semantic profile card. -->\n<article class="profile">\n  <h1>Alex Morgan</h1>\n  <p>Learning to build for the web.</p>\n  <!-- Add a descriptive portfolio link. -->\n</article>',boss:''};
const saved={challenge:docs.challenge};
const answers={};
const preview={challenge:null,boss:null};
const results={challenge:null,boss:null};
const readOnly=new Compartment();
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=(target,v=variant,st='ready')=>`?variant=${v}&screen=${target}&state=${st}`;
const link=(target,text,cls='button',st='ready')=>`<a class="${cls}" href="${url(target,variant,st)}">${text}</a>`;
function announce(text){$('#announcer').textContent='';setTimeout(()=>$('#announcer').textContent=text,20)}
function meter(n,total,label){return `<div class="meter" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${n}" aria-valuetext="${n} of ${total}"><span style="width:${n/total*100}%"></span></div>`}
function route(){return `<div class="route-map"><div class="stop done"><p class="kicker">Completed</p><h3>Text & structure</h3><p class="small muted">3 challenges recorded</p></div><div class="stop current"><p class="kicker">You are here</p><h3>Links & semantics</h3><p class="small muted">Read → check → build</p></div><div class="stop"><p class="kicker">Up next</p><h3>Forms & inputs</h3><p class="small muted">Continue the course</p></div><div class="stop"><p class="kicker">Course milestone</p><h3>Build a portfolio</h3><p class="small muted">Boss Challenge · locked</p></div></div>`}
function intro(k,title,desc=''){return `<header class="page-intro"><p class="kicker">${k}</p><h1>${title}</h1>${desc?`<p class="lead muted">${desc}</p>`:''}</header>`}
function dashboard(){if(state==='empty')return `<div class="content">${intro('Your learning','Your first course starts here.','There are no active courses with challenges yet.')}<p>Your learning path will appear when content becomes available.</p></div>`;return `<div class="content">${intro('Your learning','Make something today, Alex.','One concept. One small build. Your next step is ready.')}<div class="split"><section class="next-work"><p class="kicker">HTML foundations / Links & semantics</p><h2>Give your words a destination.</h2><p class="lead muted">Learn how meaningful links help people navigate. Then build a profile that connects to your work.</p><div class="row">${link('lesson','Continue learning →','button primary')}${link('path','See the course route','button quiet')}</div><p class="small muted space">Last recorded step: Headings Challenge completed.</p></section><aside class="journey-side"><h3>Your course route</h3>${route()}</aside></div><section class="space"><div class="course-strip"><strong>HTML foundations</strong><span class="muted">Practice: 3 of 6 challenges complete</span><span class="status muted">Boss Challenge not passed</span></div><div class="row between space"><p class="small muted">Completion is evidence of work, not a mastery score.</p>${link('progress','Review your learning evidence','button quiet')}</div></section></div>`}
function path(){return `<div class="content">${intro('Your course route','A page, from the inside out.','HTML foundations · Build structure, connect content, then create a portfolio.')}<div class="course-strip"><strong>3 / 6 practice challenges</strong><span class="muted">Boss Challenge still required for course completion</span></div><div class="path-layout"><aside><ul class="course-nav"><li class="selected">01 · HTML foundations<p>Current course</p></li><li>02 · CSS layouts<p>Complete the earlier course</p></li><li>03 · JavaScript<p>Complete the earlier course</p></li></ul></aside><section><p class="kicker">Section 02 / Links & semantics</p><h2 class="space">Connect your content.</h2><div class="lesson-row"><span class="number">01</span><div><h3>Headings with purpose</h3><p class="muted">Lesson and Challenge</p></div><span class="status good">Challenge completed</span></div><div class="lesson-row active"><span class="number">02</span><div><h3>Links that make sense</h3><p class="muted">Lesson → Knowledge Check → Profile Challenge</p></div>${link('lesson','Continue →','button primary')}</div><div class="lesson-row"><span class="number">03</span><div><h3>Forms that welcome input</h3><p class="muted">Lesson and Challenge · available within this reached course</p></div>${link('lesson','View lesson','button quiet')}</div><div class="lesson-row locked"><span class="number">04</span><div><h3>Build your portfolio</h3><p>Boss Challenge · Complete all 6 practice challenges to begin.</p></div><button data-action="lock">Why locked?</button></div><p id="lock-reason" class="small space" hidden>Complete the remaining 3 practice challenges. A preview or Knowledge Check score does not unlock this assessment.</p></section></div></div>`}
function lesson(){return `<div class="content">${link('path','← Course route','button quiet')}<div class="space">${intro('HTML foundations / Links & semantics','Links that make sense.','Use an anchor to connect a reader to the next useful place.')}</div><div class="lesson-layout"><nav class="lesson-outline" aria-label="Lesson sections"><a href="#concept">The concept</a><a href="#example">See it work</a><a href="#mistake">A common mistake</a><a href="#next">Put it into practice</a></nav><article><h2 id="concept">A link needs a destination and a name.</h2><p>The <code>&lt;a&gt;</code> element connects one resource to another. Its <code>href</code> tells the browser where to go. The words inside tell your reader why they would go there.</p><p>Good link text makes sense before someone follows it. “View my portfolio” is more useful than “Click here.”</p><h2 id="example">See the relationship.</h2><pre class="code-sample">&lt;a href="https://example.com/portfolio"&gt;\n  View my portfolio\n&lt;/a&gt;</pre><div class="example-result"><strong>Rendered example</strong><p><a href="https://example.com/portfolio" target="_blank" rel="noopener">View my portfolio ↗</a></p></div><h2 id="mistake">Don't leave the purpose behind.</h2><p>An empty anchor creates an unclear destination. Keep the link text descriptive and meaningful outside the surrounding sentence.</p><details><summary>Compare two examples</summary><pre class="code-sample">Less helpful: &lt;a href="/work"&gt;Click here&lt;/a&gt;\nMore helpful: &lt;a href="/work"&gt;Explore my work&lt;/a&gt;</pre></details><div id="next" class="continuation"><div><h3>Ready to build?</h3><p class="small muted">Complete the required Knowledge Check, then open the Challenge.</p></div>${link('check','Check your understanding →','button primary')}</div></article><aside class="margin-note"><strong>What you'll build</strong><p class="space">A semantic profile with a heading, short introduction and descriptive portfolio link.</p><p class="small muted space">First Challenge completion: 25 XP. Reading alone does not record completion.</p></aside></div></div>`}
const questions=[['What gives a link its destination?',['href','title','class']],['Which link text explains its purpose?',['Click here','View my portfolio','Go']],['Which element represents a link?',['<p>','<section>','<a>']]];
function check(){return `<div class="content">${link('lesson','← Lesson','button quiet')}<div class="space">${intro('Links & semantics / Knowledge Check','Check the idea before you build.','Three questions to prepare for your build.')}</div><div class="quiz-layout"><form id="quiz">${quizDone?`<div class="quiz-result" tabindex="-1" id="quiz-result"><h2>Check recorded · demo</h2><p>Your answers are ready for review. In CodeQuest, the server returns correctness and explanations.</p>${link('challenge','Open the Challenge →','button primary')}</div>`:''}${questions.map(([q,opts],i)=>`<fieldset id="q${i}" tabindex="-1"><legend>${i+1}. ${q}</legend>${opts.map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" ${answers[i]===String(j)?'checked':''} ${quizDone?'disabled':''}><span>${escape(o)}</span></label>`).join('')}</fieldset>`).join('')}</form><aside class="quiz-summary"><h3 id="answered">Answered ${Object.keys(answers).length} of 3</h3>${meter(Object.keys(answers).length,3,'Questions answered')}<div class="questions-nav" aria-label="Question navigator">${questions.map((q,i)=>`<button data-question="${i}" aria-label="Question ${i+1}, ${answers[i]===undefined?'unanswered':'answered'}">${i+1}${answers[i]===undefined?'':' ✓'}</button>`).join('')}</div><p class="small muted">Answer every question, then submit. Review the feedback before you build.</p><button class="primary space" data-action="check-submit" ${quizDone?'disabled':''}>Submit answers</button><p id="quiz-error" class="error space" hidden></p></aside></div></div>`}
function feedback(){const r=results[screen]||(['failed','completed','network','submitted'].includes(state)?state:null);if(r==='failed')return `<h3 id="result-heading" tabindex="-1" class="error">${screen==='boss'?'This attempt failed · demo':'Challenge not yet completed · demo'}</h3><p>${screen==='boss'?'Recorded score: 60%. Passing threshold for this attempt: 70%.':'The submitted example is missing its descriptive portfolio link.'}</p><p class="small muted space">Result for ${screen==='boss'?'recorded submission':'submitted code'}. A local preview does not change it.</p><div class="row"><button data-action="return-code">${screen==='boss'?'Review recorded code':'Return to Code'}</button></div>`;if(r==='completed')return `<h3 id="result-heading" tabindex="-1" class="good">${screen==='boss'?'Boss Challenge passed · demo':'Challenge completed · demo'}</h3><p>${screen==='boss'?'Recorded score: 80% · threshold: 70%. Course completion recorded.':'Completion recorded. Example first reward: 25 XP. Practice: 4 of 6 challenges complete.'}</p><div class="row">${link('path','Continue to course route →','button')}<button data-action="return-code">Review code</button></div>`;if(r==='network')return '<h3 id="result-heading" tabindex="-1" class="warning">Result not confirmed · demo</h3><p>Your code is retained here. Check server state before deciding whether to submit again.</p><button class="space" data-action="status">Check status</button>';if(r==='submitted')return '<h3 id="result-heading" tabindex="-1">Submission recorded · demo</h3><p>Verification is required. This is not a background queue; resume verification of the stored code.</p>';return '<h3 id="result-heading" tabindex="-1">Your result belongs here.</h3><p class="muted">Submit to check your work on the server. Run preview only renders your current code.</p>'}
function workspace(){const boss=screen==='boss',terminal=boss&&['failed','completed','submitted'].includes(state),entry=boss&&['entry','locked'].includes(state);if(terminal&&!docs.boss)docs.boss=state==='completed'?'<main>\n  <h1>Alex Morgan</h1>\n  <p>I build useful things for the web.</p>\n  <a href="https://example.com">View my portfolio</a>\n</main>':docs.challenge;return `<div class="workspace-page"><header class="workspace-head">${link(boss?'path':'lesson',boss?'← Course route':'← Lesson','button quiet return')}<div class="context"><p class="kicker">HTML foundations / ${boss?'Boss Challenge':'Challenge'}</p><h1>${boss?'Build your portfolio.':'Build a profile card.'}</h1></div><span class="status ${terminal?'info':''}">${boss?(terminal?'Recorded attempt':'Assessment · no draft'):'First completion · 25 XP'}</span></header>${entry?`<section class="assessment-entry"><p class="kicker">${state==='locked'?'Prerequisites missing':'Ready to begin'}</p><h2 class="space">${state==='locked'?'Finish the course practice first.':'Bring the course together.'}</h2>${state==='entry'?'<p class="status good">Eligible fixture · 6 of 6 practice challenges completed</p>':''}<p>Build a semantic portfolio with an introduction and descriptive links. The server scores the submitted code. Passing completes this course.</p><p class="small muted">No hints, solution reveal, timer or server draft. A retry creates a fresh blank assessed attempt.</p>${state==='locked'?link('path','View remaining practice','button primary'):'<button class="primary" data-action="begin">Begin assessment</button>'}</section>`:`<div class="pane-tabs" role="tablist" aria-label="Workspace modes">${['task','code','output'].map(p=>`<button role="tab" id="tab-${p}" aria-controls="pane-${p}" aria-selected="${pane===p}" tabindex="${pane===p?'0':'-1'}" data-pane-target="${p}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div><div class="workspace-body"><section class="editor-pane ${pane==='code'?'active':''}" id="pane-code" data-pane="code"><div class="pane-head"><h2>HTML source ${terminal?'· read-only':''}</h2><span id="source-state">${boss?(terminal?'Recorded submission':'Not saved to server'):'Saved draft · demo'}</span></div><div class="editor-host" id="editor-host"></div></section><aside class="task-pane ${pane==='task'?'active':''}" id="pane-task" data-pane="task"><div><div class="row between"><p class="kicker">Your task</p><button class="quiet task-toggle" data-action="task">Hide</button></div><h2>${boss?'Build a useful portfolio.':'Make an introduction.'}</h2><p class="muted">${boss?'Combine the course concepts into a semantic page that presents your work.':'Create a semantic profile that introduces Alex and links to a portfolio.'}</p></div><div><h3>Public instructions</h3><ol><li>Use a meaningful top-level heading.</li><li>Write a short introduction.</li><li>Add a descriptive portfolio link.</li></ol><p class="small muted">${boss?'Passing threshold for a new attempt: 70%. Results are decided by the server.':'Preview is optional. Submit checks the server requirements; a genuine failed submission uses the existing XP penalty.'}</p>${boss||state==='completed'?'':`<details id="help"><summary>Assistance</summary><p>Next hint: 5 XP. Reveal only after confirming the server cost.</p><button data-action="hint">Review hint cost</button><p id="hint-text" hidden class="space">Demo entitled hint: give the anchor an href and meaningful text. No real XP was spent.</p></details>`}</div></aside><section class="output-pane ${pane==='output'?'active':''}" id="pane-output" data-pane="output"><div class="output-tabs" role="tablist" aria-label="Output views"><button role="tab" id="tab-feedback" aria-controls="feedback-content" aria-selected="${output==='feedback'}" tabindex="${output==='feedback'?0:-1}" data-output="feedback">Feedback</button><button role="tab" id="tab-preview" aria-controls="preview-content" aria-selected="${output==='preview'}" tabindex="${output==='preview'?0:-1}" data-output="preview">Preview</button><span id="preview-status" class="muted">${preview[screen]?'Earlier preview available':'No preview run yet'}</span></div><div class="output-content" role="tabpanel" id="feedback-content" aria-labelledby="tab-feedback" ${output==='feedback'?'':'hidden'}>${feedback()}</div><div class="output-content" role="tabpanel" id="preview-content" aria-labelledby="tab-preview" ${output==='preview'?'':'hidden'}><h3 id="preview-heading" tabindex="-1">Local preview</h3><p id="preview-empty" class="small muted" ${preview[screen]?'hidden':''}>Run preview to see the current code. This does not grade it.</p><iframe title="Local preview for ${boss?'portfolio':'profile'} challenge" class="preview-frame" sandbox="" ${preview[screen]?'':'hidden'}></iframe><button class="space" data-action="return-code">Return to Code</button></div></section></div><footer class="toolbar"><div class="utilities">${boss||state==='completed'?'':`<button data-action="help">Help</button>${state==='completed'?'':'<button data-action="save">Save draft</button>'}`}<button class="task-toggle quiet" data-action="task">Task</button></div><span class="source-status" id="draft-state">${boss?(terminal?'Recorded source; edits closed':'Edits stay here until you submit'):'Manual draft · demo only'}</span><button data-action="run">Run preview</button>${state==='network'?'<button class="primary" data-action="status">Check status</button>':terminal?(state==='submitted'?'<button class="primary" data-action="resume">Resume verification</button>':state==='completed'?'<button data-action="retry">Retry assessment</button>'+link('path','Continue →','button primary'):'<button class="primary" data-action="retry">Retry assessment</button>'):state==='completed'?link('path','Continue →','button primary'):`<button class="primary" data-action="submit">Submit ${boss?'assessment':'challenge'}</button>`}</footer>`}</div>`}
function progress(){return `<div class="content">${intro('Learning record','See the evidence, not a guess.','Completion, assessment results and skill evidence answer different questions.')}<div class="course-strip"><strong>HTML foundations</strong><span>Practice 3 / 6</span><span>Boss Challenge not passed</span><span class="status info">Course in progress</span></div><h2 class="section-heading">Knowledge Check & Challenge evidence</h2><p class="muted">Skill values combine mapped correctness and recorded Challenge completion. Boss evidence is separate.</p>${[['Text structure',87.5,'3 / 4 mapped challenges · 2 / 2 check responses'],['Links & semantics',50,'1 / 2 mapped challenges · no check evidence'],['Forms',null,'No recorded evidence yet']].map(([name,n,desc])=>`<section class="evidence-row"><div><h3>${name}</h3><p class="small muted">${desc}</p></div><div>${n===null?'Not assessed':`${n}% of available evidence${meter(n,100,name+' evidence')}`}</div><details><summary>Why this result?</summary><p class="small">${n===null?'Missing evidence does not imply weak ability.':'Example fixture using the existing source-weighting model. The backend supplies the actual value.'}</p></details></section>`).join('')}<h2 class="section-heading">Recorded activity</h2><table><thead><tr><th scope="col">Work</th><th scope="col">Evidence</th><th scope="col">XP</th></tr></thead><tbody><tr><td>Headings Challenge</td><td>Completed</td><td>25 earned</td></tr><tr><td>Links lesson</td><td>No completion claim</td><td>—</td></tr></tbody></table>${link('path','Return to course route','button space')}</div>`}
function render(){view?.destroy();view=null;document.body.dataset.variant=variant;const nav=screen==='dashboard'?'dashboard':screen==='boss'?'boss':'path';$('#app').innerHTML=`<header class="topbar">${link('dashboard','<code aria-hidden="true">&lt;/&gt;</code> CodeQuest','brand')}<nav aria-label="Primary">${[['dashboard','Dashboard'],['path','Learn'],['boss','Boss Challenges']].map(([s,t])=>`<a href="${url(s,variant,s==='boss'?'locked':'ready')}" ${nav===s?'aria-current="page"':''}>${t}</a>`).join('')}</nav><details class="account"><summary><span class="mono">450 XP</span><strong>Alex</strong></summary><ul><li>${link('progress','Learning record','')}</li><li>${link('progress','Competency evidence','')}</li></ul></details></header><div class="lab"><strong>DESIGN LAB</strong><label>Screen <select id="screen-select">${screens.map(s=>`<option value="${s}" ${s===screen?'selected':''}>${labels[s]}</option>`).join('')}</select></label><label>Fixture <select id="state-select">${['ready','empty','entry','locked','failed','completed','submitted','network'].map(s=>`<option ${s===state?'selected':''}>${s}</option>`).join('')}</select></label><span>Sample data · no backend writes or real XP</span></div><main id="main" tabindex="-1">${screen==='dashboard'?dashboard():screen==='path'?path():screen==='lesson'?lesson():screen==='check'?check():screen==='progress'?progress():workspace()}</main>${import.meta.env.DEV?`<div class="design-switcher" aria-label="Design direction switcher"><button data-variant="prev" aria-label="Previous design direction">←</button><strong>${names[variant]}</strong><button data-variant="next" aria-label="Next design direction">→</button></div>`:''}`;
if($('#editor-host')){const terminal=screen==='boss'&&['failed','completed','submitted'].includes(state);view=new EditorView({doc:docs[screen],parent:$('#editor-host'),extensions:[basicSetup,html(),oneDark,readOnly.of([EditorState.readOnly.of(terminal),EditorView.editable.of(!terminal)]),EditorView.contentAttributes.of({'aria-label':`HTML code for ${screen==='boss'?'portfolio assessment':'profile challenge'}`,'aria-describedby':'source-state',tabindex:'0'}),EditorView.updateListener.of(u=>{if(u.docChanged){docs[screen]=u.state.doc.toString();$('#source-state').textContent=screen==='boss'?'Not saved to server':'Unsaved changes';$('#draft-state').textContent='Current edits';if(preview[screen])$('#preview-status').textContent='Preview is from earlier code';}})]});window.prototypeEditor=view;if(preview[screen])$('iframe').srcdoc=preview[screen];}else window.prototypeEditor=null;
const setPanelRoles=()=>{document.querySelectorAll('[data-pane]').forEach(el=>{if(matchMedia('(max-width:1100px)').matches){el.setAttribute('role','tabpanel');el.setAttribute('aria-labelledby','tab-'+el.dataset.pane)}else{el.removeAttribute('role');el.removeAttribute('aria-labelledby')}})};setPanelRoles();window.onresize=setPanelRoles;
$('#screen-select').onchange=e=>go(e.target.value);$('#state-select').onchange=e=>{state=e.target.value;results[screen]=null;pane=['failed','completed','network','submitted'].includes(state)?'output':'code';sync();render()};
$('#quiz')?.addEventListener('change',e=>{answers[e.target.name.slice(1)]=e.target.value;$('#answered').textContent=`Answered ${Object.keys(answers).length} of 3`;const m=$('.quiz-summary .meter');m.setAttribute('aria-valuenow',Object.keys(answers).length);m.firstElementChild.style.width=Object.keys(answers).length/3*100+'%';document.querySelectorAll('[data-question]').forEach(b=>{const answered=answers[b.dataset.question]!==undefined;b.textContent=Number(b.dataset.question)+1+(answered?' ✓':'');b.setAttribute('aria-label',`Question ${Number(b.dataset.question)+1}, ${answered?'answered':'unanswered'}`)});announce($('#answered').textContent)});
}
function sync(){history.replaceState(null,'',url(screen,variant,state))}
function go(target){screen=target;state=target==='boss'?'entry':'ready';pane='code';sync();render();$('#main').focus();window.scrollTo(0,0)}
function choosePane(p,focus=false){pane=p;document.querySelectorAll('[data-pane]').forEach(e=>e.classList.toggle('active',e.dataset.pane===p));document.querySelectorAll('[data-pane-target]').forEach(b=>{const active=b.dataset.paneTarget===p;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});if(focus){if(p==='code')view?.focus();else (p==='output'?$('#result-heading'):$('#pane-task')).focus?.()}}
function chooseOutput(o){output=o;document.querySelectorAll('[data-output]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.output===o);b.tabIndex=b.dataset.output===o?0:-1});$('#feedback-content').hidden=o!=='feedback';$('#preview-content').hidden=o!=='preview'}
async function act(action){if(action==='lock'){$('#lock-reason').hidden=false;announce($('#lock-reason').textContent)}if(action==='task')$('#pane-task').classList.toggle('closed');if(action==='help'){choosePane('task');$('#help').open=true;$('#help summary').focus()}if(action==='hint'){if(confirm('Design demo: reveal a hint for the displayed 5 XP cost? No real XP is spent.')){$('#hint-text').hidden=false;announce('Example hint revealed. No real XP spent.')}}if(action==='return-code'){choosePane('code');view?.focus()}if(action==='save'){const captured=docs[screen];$('#draft-state').textContent='Saving draft · demo';await new Promise(r=>setTimeout(r,500));saved[screen]=captured;$('#draft-state').textContent=docs[screen]===captured?'Draft saved in memory · demo':'Earlier version saved; current edits unsaved';announce($('#draft-state').textContent)}if(action==='run'){preview[screen]=docs[screen];choosePane('output');chooseOutput('preview');$('iframe').hidden=false;$('#preview-empty').hidden=true;$('iframe').srcdoc=preview[screen];$('#preview-status').textContent='Preview loaded · not graded';$('#preview-heading').focus();announce('Local preview loaded. Not graded.')}if(action==='submit'||action==='resume'){if(screen==='boss'&&action==='submit'&&!confirm('Record this code for this assessment attempt? A later change requires a new blank retry. Design demo only.'))return;choosePane('output');chooseOutput('feedback');$('#feedback-content').innerHTML='<h3 id="pending" tabindex="-1">Checking submitted code · demo</h3><p>This example simulates a server response.</p>';$('#pending').focus();document.querySelectorAll('.toolbar button').forEach(b=>b.disabled=true);view.dispatch({effects:readOnly.reconfigure([EditorState.readOnly.of(true),EditorView.editable.of(false)])});await new Promise(r=>setTimeout(r,650));results[screen]=state==='failed'?'failed':'completed';state=results[screen];sync();render();choosePane('output');$('#result-heading')?.focus();announce('Example result displayed. No real academic state changed.')}if(action==='retry'){docs.boss='';results.boss=null;preview.boss=null;state='ready';pane='code';sync();render();view?.focus();announce('New blank assessment attempt · demo')}if(action==='begin'){state='ready';sync();render();view?.focus()}if(action==='status'){announce('Demo status still unresolved; do not automatically resubmit.')}if(action==='check-submit'){const missing=questions.findIndex((_,i)=>answers[i]===undefined);if(missing>=0){$('#quiz-error').hidden=false;$('#quiz-error').textContent=`Question ${missing+1} is unanswered.`;$('#q'+missing).focus();announce($('#quiz-error').textContent)}else{quizDone=true;render();$('#quiz-result').focus();announce('Check recorded · demo. Actual correctness comes from the server.')}}}
document.addEventListener('click',e=>{const v=e.target.closest('button[data-variant]');if(v){variant=variants[(variants.indexOf(variant)+(v.dataset.variant==='next'?1:3))%4];sync();render();announce(names[variant]);return}const b=e.target.closest('[data-pane-target]');if(b){choosePane(b.dataset.paneTarget);return}const o=e.target.closest('[data-output]');if(o){chooseOutput(o.dataset.output);return}const q=e.target.closest('[data-question]');if(q){$('#q'+q.dataset.question).focus();return}const a=e.target.closest('[data-action]');if(a){act(a.dataset.action);return}const l=e.target.closest('a[href^="?"]');if(l){e.preventDefault();const p=new URLSearchParams(l.search);screen=p.get('screen');state=p.get('state')||'ready';pane='code';sync();render();$('#main').focus();window.scrollTo(0,0)}});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(tab&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){const ts=[...tab.parentElement.querySelectorAll('[role=tab]')];let i=ts.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?ts.length-1:(i+(e.key==='ArrowRight'?1:ts.length-1))%ts.length;e.preventDefault();ts[i].click();ts[i].focus();return}if(e.target.closest('input,textarea,select,button,a,summary,[contenteditable],.cm-editor,[role=tablist]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){variant=variants[(variants.indexOf(variant)+(e.key==='ArrowRight'?1:3))%4];sync();render();announce(names[variant])}});
render();
